export function MentionPicker({
  label = "{{label}}",
  query = "{{query}}",
  accent = "{{accent}}",
  expanded = {{expanded}},
  displayStyle = "{{displayStyle}}",
}) {
  const people = [
    { initials: "SK", name: "Samira Khan", handle: "@samira", selected: true },
    { initials: "SC", name: "Sam Chen", handle: "@samc", selected: false },
    { initials: "SP", name: "Samuel Park", handle: "@spark", selected: false },
  ];
  const showName = displayStyle !== "handle";
  const showHandle = displayStyle !== "name";
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, color: "#241430", background: "#FAF7F2", maxWidth: 260, width: 260, padding: 14, borderRadius: 12, boxSizing: "border-box" }}>
      <label htmlFor="mpr-input" style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#241430a0", marginBottom: 5 }}>{label}</label>
      <input id="mpr-input" type="text" role="combobox" aria-expanded={expanded} aria-controls="mpr-listbox" aria-autocomplete="list" defaultValue={`@${query}`} autoComplete="off" style={{ display: "block", width: "100%", boxSizing: "border-box", padding: "7px 10px", border: `1.5px solid ${accent}`, borderRadius: 8, font: "inherit", color: "#241430", background: "#fff" }} />
      {expanded && (
        <ul id="mpr-listbox" role="listbox" aria-label="Matching people" style={{ listStyle: "none", margin: "6px 0 0", padding: 4, background: "#fff", borderRadius: 10, boxShadow: "0 4px 14px rgba(36,20,48,.14)" }}>
          {people.map((p) => (
            <li key={p.handle} role="option" aria-selected={p.selected} style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 8px", borderRadius: 6, background: p.selected ? accent : "transparent" }}>
              <span aria-hidden="true" style={{ width: 22, height: 22, borderRadius: "50%", background: "#241430", color: "#FAF7F2", fontSize: 9, fontWeight: 700, display: "grid", placeItems: "center", flexShrink: 0 }}>{p.initials}</span>
              {showName && <span style={{ fontWeight: 600 }}>{p.name}</span>}
              {showHandle && <span style={{ fontSize: 11, color: "#241430a0" }}>{p.handle}</span>}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
